import React, { useState } from 'react';
import { View, Text, Modal, TouchableOpacity, TextInput, Image, Switch, StyleSheet } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { BRAND } from './theme';

const THOUGHT_EMOJIS = ['❤️', '🥺', '😭', '😂', '🥰', '💔', '😔', '💯'];

export function ReelModals({
  thoughtReel, setThoughtReel, me, onSaveThought, onUndoRepost,
    menuReel, setMenuReel, onNotInterested, onReport,
      playbackOpen, setPlaybackOpen, fullscreen, setFullscreen, autoScroll, setAutoScroll, captions, setCaptions,
      }: any) {
        const [thought, setThought] = useState('');

          return (
              <>
                    <Modal visible={!!thoughtReel} animationType="fade" transparent>
                            <View style={styles.darkBg}>
                                      <View style={styles.thoughtCard}>
                                                  <TextInput
                                                                style={styles.bubble} placeholder="Add a thought..." placeholderTextColor="#6B7280"
                                                                              value={thought} onChangeText={setThought}
                                                                                          />
                                                                                                      {me?.avatar ? <Image source={{ uri: me.avatar }} style={styles.av} /> : (
                                                                                                                    <View style={[styles.av, { backgroundColor: BRAND, justifyContent: 'center', alignItems: 'center' }]}>
                                                                                                                                    <Text style={{ color: '#fff', fontSize: 22, fontWeight: '800' }}>{(me?.username || 'U')[0].toUpperCase()}</Text>
                                                                                                                                                  </View>
                                                                                                                                                              )}
                                                                                                                                                                          <TouchableOpacity onPress={() => { onUndoRepost(thoughtReel?.id); setThoughtReel(null); }}>
                                                                                                                                                                                        <Text style={{ color: '#EF4444', fontWeight: '700', marginTop: 10 }}>You reposted this reel • Delete</Text>
                                                                                                                                                                                                    </TouchableOpacity>
                                                                                                                                                                                                                <View style={styles.emojiRow}>
                                                                                                                                                                                                                              {THOUGHT_EMOJIS.map((e) => (
                                                                                                                                                                                                                                              <TouchableOpacity key={e} onPress={() => setThought((p) => p + e)}><Text style={{ fontSize: 24 }}>{e}</Text></TouchableOpacity>
                                                                                                                                                                                                                                                            ))}
                                                                                                                                                                                                                                                                        </View>
                                                                                                                                                                                                                                                                                    <TouchableOpacity style={styles.saveBtn} onPress={() => { onSaveThought(thoughtReel, thought); setThought(''); setThoughtReel(null); }}>
                                                                                                                                                                                                                                                                                                  <Text style={{ color: '#111827', fontWeight: '800', fontSize: 16 }}>Save</Text>
                                                                                                                                                                                                                                                                                                              </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                        </View>
                                                                                                                                                                                                                                                                                                                                </View>
                                                                                                                                                                                                                                                                                                                                      </Modal>

                                                                                                                                                                                                                                                                                                                                            <Modal visible={!!menuReel} animationType="slide" transparent>
                                                                                                                                                                                                                                                                                                                                                    <View style={styles.shBg}>
                                                                                                                                                                                                                                                                                                                                                              <View style={styles.shCard}>
                                                                                                                                                                                                                                                                                                                                                                          <View style={styles.handle} />
                                                                                                                                                                                                                                                                                                                                                                                      <Text style={styles.shTitle}>About this reel</Text>
                                                                                                                                                                                                                                                                                                                                                                                                  <Text style={{ color: '#6B7280', fontSize: 13, marginBottom: 14 }}>Original audio • @{menuReel?.username || 'user'}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity style={styles.mRow} onPress={() => { setMenuReel(null); setPlaybackOpen(true); }}>
                                                                                                                                                                                                                                                                                                                                                                                                                            <Ionicons name="play-circle-outline" size={22} color="#111827" /><Text style={styles.mTxt}>Playback</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                        </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                    <TouchableOpacity style={styles.mRow} onPress={() => setMenuReel(null)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Ionicons name="checkmark-circle-outline" size={22} color="#111827" /><Text style={styles.mTxt}>Interested</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <TouchableOpacity style={styles.mRow} onPress={() => { onNotInterested(menuReel?.id); setMenuReel(null); }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Ionicons name="close-circle-outline" size={22} color="#111827" /><Text style={styles.mTxt}>Not interested</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <TouchableOpacity style={styles.mRow} onPress={() => { onReport(menuReel?.id); setMenuReel(null); }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Ionicons name="alert-circle-outline" size={22} color="#EF4444" /><Text style={[styles.mTxt, { color: '#EF4444' }]}>Report</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <TouchableOpacity style={styles.cancelBtn} onPress={() => setMenuReel(null)}><Text style={{ fontWeight: '700' }}>Close</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </Modal>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Modal visible={playbackOpen} animationType="slide" transparent>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <View style={styles.shBg}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <View style={styles.shCard}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <View style={styles.handle} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Text style={[styles.shTitle, { textAlign: 'center' }]}>Playback</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <View style={styles.mRow}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Ionicons name="scan-outline" size={22} color="#111827" /><Text style={[styles.mTxt, { flex: 1 }]}>View fullscreen</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Switch value={fullscreen} onValueChange={setFullscreen} trackColor={{ true: BRAND }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <View style={styles.mRow}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Ionicons name="repeat-outline" size={22} color="#111827" /><Text style={[styles.mTxt, { flex: 1 }]}>Auto scroll</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Switch value={autoScroll} onValueChange={setAutoScroll} trackColor={{ true: BRAND }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <View style={styles.mRow}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Ionicons name="text-outline" size={22} color="#111827" /><Text style={[styles.mTxt, { flex: 1 }]}>Closed Captions</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Switch value={captions} onValueChange={setCaptions} trackColor={{ true: BRAND }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <TouchableOpacity style={styles.cancelBtn} onPress={() => setPlaybackOpen(false)}><Text style={{ fontWeight: '700' }}>Done</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </Modal>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const styles = StyleSheet.create({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      darkBg: { flex: 1, backgroundColor: 'rgba(0,0,0,0.72)', justifyContent: 'center', alignItems: 'center', padding: 20 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        thoughtCard: { width: '100%', alignItems: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          bubble: { backgroundColor: '#fff', color: '#111827', borderRadius: 20, paddingHorizontal: 18, paddingVertical: 12, fontSize: 15, minWidth: 180, textAlign: 'center', marginBottom: 10 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            av: { width: 64, height: 64, borderRadius: 32, borderWidth: 2, borderColor: '#fff' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              emojiRow: { flexDirection: 'row', gap: 12, marginVertical: 20 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                saveBtn: { backgroundColor: '#fff', width: '100%', padding: 14, borderRadius: 14, alignItems: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  shBg: { flex: 1, backgroundColor: 'rgba(0,0,0,0.45)', justifyContent: 'flex-end' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    shCard: { backgroundColor: '#fff', borderTopLeftRadius: 22, borderTopRightRadius: 22, padding: 18 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      handle: { width: 40, height: 4, backgroundColor: '#D1D5DB', borderRadius: 2, alignSelf: 'center', marginBottom: 12 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        shTitle: { fontSize: 17, fontWeight: '800', color: '#111827', marginBottom: 4 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          mRow: { flexDirection: 'row', alignItems: 'center', gap: 14, paddingVertical: 13 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mTxt: { fontSize: 15, fontWeight: '600', color: '#111827' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              cancelBtn: { backgroundColor: '#F3F4F6', padding: 13, borderRadius: 12, alignItems: 'center', marginTop: 8 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              